#[derive(Clone, Copy)]
struct FalconSourceJoint {
    parent: i16,
    flags: u32,
    rotation: SourceVec3Gen,
    scale: SourceVec3Gen,
    translation: SourceVec3Gen,
}

#[derive(Clone, Copy)]
struct FalconFigaTrack {
    node_index: usize,
    obj_type: u8,
    startframe: u16,
    frac_value: u8,
    frac_slope: u8,
    length: u16,
    data: &'static [u8],
}

struct FalconFigaAction {
    clear_transn_after_anim: bool,
    tracks: &'static [FalconFigaTrack],
}

#[derive(Clone, Copy, Default)]
struct SourceVec3Gen {
    x: f32,
    y: f32,
    z: f32,
}

#[derive(Clone, Copy, Default)]
struct SourceSrt {
    rotation: SourceVec3Gen,
    scale: SourceVec3Gen,
    translation: SourceVec3Gen,
}

#[derive(Clone, Copy, Default)]
struct SourceMatrix {
    m: [[f32; 4]; 3],
}

